export const meta = {
  name: 'verify-phase47-review-fixes',
  description: 'Adversarially verify the deleteFileVersion pin-leak fix and new cas/client tests before commit',
  phases: [{ title: 'Review' }, { title: 'Synthesize' }],
}

// The uncommitted working-tree diff under review (vs HEAD 78e5f3d59):
//   packages/sdk/src/client.ts            — deleteFileVersion now returns { deletedCid, prunedCids }
//   apps/web/src/hooks/useFileVersions.ts — handleDeleteVersion captures + unpins prunedCids
//   packages/sdk-core/src/__tests__/cas.test.ts        — +2 tests (null re-resolve; multi-round dedup)
//   packages/sdk/src/__tests__/client-file-ops.test.ts — +1 test (returns prunedCids)

const REPO = '/Users/myankelev/Code/random/cipher-box'

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['findings', 'verdict'],
  properties: {
    verdict: { type: 'string', enum: ['ship', 'fix-needed', 'concerns'] },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['severity', 'file', 'issue', 'recommendation'],
        properties: {
          severity: { type: 'string', enum: ['blocker', 'major', 'minor', 'nit'] },
          file: { type: 'string' },
          issue: { type: 'string' },
          recommendation: { type: 'string' },
        },
      },
    },
  },
}

const lenses = [
  {
    key: 'pin-leak-correctness',
    prompt: `You are reviewing an uncommitted fix in the cipher-box repo (working tree vs HEAD). Run \`cd ${REPO} && git --no-pager diff\` to see ALL uncommitted changes, and read surrounding context with Read as needed.

FOCUS: correctness of the deleteFileVersion pin-leak fix in packages/sdk/src/client.ts and apps/web/src/hooks/useFileVersions.ts.

The change: deleteFileVersion previously returned { deletedCid } and discarded updateFileMetadata's prunedCids; now it returns { deletedCid, prunedCids } and the web hook unpins both deletedCid and each prunedCid.

Adversarially check, citing file:line:
1. DOUBLE-UNPIN: can deletedCid ever also appear in prunedCids (e.g. a 409-conflict merge re-adds then re-prunes the just-deleted version)? If so, is double-unpin harmful or benign? unpinFromIpfs semantics matter — inspect them.
2. RETURN THREADING: is prunedCids correctly captured from sdkCore.updateFileMetadata and returned on all paths (including the key-migration branch)? Is the finally{ fileIpnsPrivateKey.fill(0) } still correct after wrapping the call in destructuring assignment?
3. Compare against the sibling methods replaceFile and restoreFileVersion (same file) — is deleteFileVersion now consistent with how they capture/return/unpin prunedCids? Note the restore HOOK unpins web-computed prunedCids, not the SDK return — is the delete hook's use of the SDK return correct given delete computes no web-side prunedCids?
4. Any error-path / await-ordering regression introduced by the edit.

Report concrete findings only. If solid, verdict 'ship'.`,
  },
  {
    key: 'test-validity',
    prompt: `You are reviewing uncommitted test additions in cipher-box (working tree vs HEAD). Run \`cd ${REPO} && git --no-pager diff\` and read packages/sdk-core/src/cas.ts (the publishWithCas engine) and the new tests.

FOCUS: do the NEW tests actually exercise the intended engine branches and assert correctly (no false-positives / tautologies)?

New tests:
- packages/sdk-core/src/__tests__/cas.test.ts: "Test 4b" (prunedCids accumulate+dedupe across multiple merge rounds, expect ['cidA','cidB','cidC'] length 3) and "Test 4c" (409 then resolveIpnsRecord returns null → throws ConflictError, decodeRemote+merge NOT called, attempts===1).
- packages/sdk/src/__tests__/client-file-ops.test.ts: deleteFileVersion returns prunedCids from a mocked updateFileMetadata.

Adversarially check, citing file:line in cas.ts:
1. Trace publishWithCas for Test 4b: with maxAttempts default, two 409s + two resolve results + merge mocked twice — does the engine actually run exactly 2 merge rounds then succeed? Is the de-dup at the Set line real, and is the EXPECTED ORDER ['cidA','cidB','cidC'] guaranteed by insertion order? Could the test pass for the wrong reason?
2. Test 4c: does the engine throw ConflictError with attempts===1 when resolve returns null on the FIRST 409? Confirm decodeRemote/merge are unreachable on that path. Is mockResolvedValue(null) the right null shape the engine checks (\`if (!resolved)\`)?
3. Are the mocks consistent with makeParams defaults (backoff:false so no timers needed)? Any hoisting/mock-bleed risk between tests given vi.clearAllMocks in beforeEach?
4. Is the client-file-ops test meaningfully asserting the new behavior (not just the pre-existing deletedCid)?

Report concrete findings only. If the tests are valid and non-tautological, verdict 'ship'.`,
  },
  {
    key: 'scope-regression',
    prompt: `You are reviewing an uncommitted change in cipher-box (working tree vs HEAD). Run \`cd ${REPO} && git --no-pager diff\`.

FOCUS: regression surface and scope of changing deleteFileVersion's return type from Promise<{ deletedCid?: string }> to Promise<{ deletedCid?: string; prunedCids: string[] }>.

Adversarially check, citing file:line:
1. Find EVERY caller of client.deleteFileVersion across the repo (grep apps/ packages/). Does the return-type widening break any caller or test (e.g. exact-equality assertions on the result object, or a typed consumer)? 
2. Is there any other consumer (web hook, export surface, type re-export) that needs updating?
3. SCOPE CHECK: the restoreFileVersion web hook unpins web-computed prunedCids and discards the SDK's returned prunedCids — does that path have the SAME latent conflict-merge pin leak this PR fixes for delete? State clearly whether it is in-scope for the CodeRabbit finding (which named ONLY deleteFileVersion) or should be left as a separate follow-up. Do NOT recommend expanding scope unless it's a true correctness blocker.
4. Any lint concern (unused vars, the new \`let prunedCids\` in the hook) or markdownlint/commit-format risk.

Report concrete findings only. If scope is correct and no regressions, verdict 'ship'.`,
  },
]

phase('Review')
const reviews = await parallel(
  lenses.map((l) => () =>
    agent(l.prompt, { label: `review:${l.key}`, phase: 'Review', schema: SCHEMA, agentType: 'Explore' })
  )
)

phase('Synthesize')
const valid = reviews.filter(Boolean)
const allFindings = valid.flatMap((r, i) => (r.findings || []).map((f) => ({ ...f, lens: lenses[i]?.key })))
const actionable = allFindings.filter((f) => f.severity === 'blocker' || f.severity === 'major')

return {
  perLensVerdicts: valid.map((r, i) => ({ lens: lenses[i]?.key, verdict: r.verdict })),
  totalFindings: allFindings.length,
  actionable,
  allFindings,
}

